T="'inv_locations','inv_skus','inv_stocks','commerce_listings','commerce_customers','product_measurement_tasks','product_measurement_requesters','product_measurement_assets','inv_handheld_notifications','commerce_customer_notifications','user_roles','user_location_perms','measurement_mutations'"
psql -At -c "select 'CREATE TABLE public.'||table_name||' ('||string_agg(quote_ident(column_name)||' '||case when data_type='ARRAY' then (select format_type(a.atttypid,a.atttypmod) from pg_attribute a where a.attrelid=('public.'||table_name)::regclass and a.attname=column_name) when data_type='USER-DEFINED' then 'public.'||udt_name else (select format_type(a.atttypid,a.atttypmod) from pg_attribute a where a.attrelid=('public.'||table_name)::regclass and a.attname=column_name) end||case when column_default is not null and column_default !~ 'nextval|gen_ean|gen_' or column_default like 'gen_random_uuid%' then ' DEFAULT '||column_default else '' end||case when is_nullable='NO' then ' NOT NULL' else '' end, ', ' order by ordinal_position)||');' from information_schema.columns where table_schema='public' and table_name in ($T) group by table_name"
psql -At -c "select replace(indexdef,'CREATE ','CREATE ')||';' from pg_indexes where schemaname='public' and tablename in ($T) and indexdef like '%UNIQUE%'"
psql -At -c "select 'ALTER TABLE '||conrelid::regclass||' ADD CONSTRAINT '||conname||' '||pg_get_constraintdef(oid)||';' from pg_constraint where contype='c' and conrelid in (select ('public.'||t)::regclass from unnest(array[$T]) t)"
